import numpy as np
from scipy.spatial.transform import Rotation as Rot
Q=np.array([-0.40149289,0.30644506,0.27722451,-0.47036123,-0.40417305,0.9420799,-0.41880158])
def T(xyz=(0,0,0),rpy=(0,0,0)):
 M=np.eye(4); M[:3,:3]=Rot.from_euler('xyz',rpy).as_matrix(); M[:3,3]=xyz; return M
def Rz(a):return T(rpy=(0,0,a))
ORIG=[T((0,0,.333)),T(rpy=(-np.pi/2,0,0)),T((0,-.316,0),rpy=(np.pi/2,0,0)),T((.0825,0,0),rpy=(np.pi/2,0,0)),T((-.0825,.384,0),rpy=(-np.pi/2,0,0)),T(rpy=(np.pi/2,0,0)),T((.088,0,0),rpy=(np.pi/2,0,0))]
def fk(q):
 H=np.eye(4); out=[]
 for A,qi in zip(ORIG,q):
  H=H@A@Rz(qi); out.append(H.copy())
 out.append(H@T((0,0,.107),rpy=(0,0,-np.pi/4)))
 return out
if __name__=='__main__':
 for i,m in enumerate(fk(Q)):print(i+1,m[:3,3],m[:3,:3])
